    :POKEMON_NURSE => {:label => "PokemonNurseCard", :type => "TYPE_TRAINER", :gfx => "pokemon_nurse", :name => "Pokémon Nurse", :rarity => "DIAMOND", :sets => ["NEO"], :effect => "Neo5PokemonNurseEffectCommands", :desc => "Remove all damage counters from 1\nof your Pokémon. Then discard all\nEnergy cards attached to it, if\nany."}
  }

  NEO_CARDS.each { |id, h| CARDS[id] = h }
  # after the original Pokemon, before the Trainers
  CARD_ORDER.insert(CARD_ORDER.index(:PROFESSOR_OAK), *(NEO_CARDS.keys - CARD_ORDER))
end
